import json, subprocess, re
# reuse fitter output by parsing its printed prediction
out = subprocess.run(["python","scripts/fit.py","settings.json"],capture_output=True,text=True).stdout
pred={}
for line in out.splitlines():
    m=re.match(r"(P\d+) = \S+: (.*)",line)
    if m:
        pred[m.group(1)]={kv.split()[0]:float(kv.split()[1]) for kv in m.group(2).split(", ")}
json.dump({"prediction":pred,"rationale":"With 179 given visits and 45 to predict, I tried matching windows from 4 to 24 visits in steps of 2, leaving enough blocks; the fitter chose m=24 (R=0.30 <= nu=0.5), the longest window that still matched within threshold, capturing the parcel's strong seasonal cycle. Bandwidth candidates 10-60 days let CV pick light smoothing per band. max_donors=20 spread blocks over the four-year history, and a small zeta=0.01 let stepwise selection keep three well-fitting seasonal analogues (weights 0.22/0.41/0.37), whose forward parts give the forecast."},open("answer.json","w"),indent=1)
print(len(pred),"visits written")
EOF
